#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    std::vector<int> onceTwice(std::vector<int>& nums) {
        std::unordered_map<int, int> counts;
        for (int x : nums) counts[x]++;

        std::vector<int> res;
        for (const auto& [val, freq] : counts) {
            if (freq == 1) res.push_back(val);
        }
        std::sort(res.begin(), res.end());
        return res;
    }
};

import java.util.*;

class Solution {
    public int[] onceTwice(int[] nums) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int x : nums) counts.put(x, counts.getOrDefault(x, 0) + 1);

        List<Integer> res = new ArrayList<>();
        for (var entry : counts.entrySet()) {
            if (entry.getValue() == 1) res.add(entry.getKey());
        }
        Collections.sort(res);

        int[] arr = new int[res.size()];
        for (int i = 0; i < res.size(); i++) arr[i] = res.get(i);
        return arr;
    }
}

