var onceTwice = function(nums) {
    const counts = new Map();
    for (const x of nums) {
        counts.set(x, (counts.get(x) || 0) + 1);
    }

    const res = [];
    for (const [val, freq] of counts.entries()) {
        if (freq === 1) res.push(val);
    }
    res.sort((a, b) => a - b);
    return res;
};
